  app.post("/api/collaboration/tasks", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { patientId: bodyPatientId, careTeamId: bodyCareTeamId } = req.body as any;

      if (bodyCareTeamId) {
        const teamAccess = await providerCollaborationService.hasUserAccessToCareTeam(bodyCareTeamId, userId);
        if (!teamAccess) {
          return res.status(403).json({ error: "Access denied: not a member of the specified care team" });
        }
      }

      if (bodyPatientId && bodyPatientId !== userId) {
        const providerProfile = await storage.getProviderProfileByUserId(userId);
        if (!providerProfile) {
          return res.status(403).json({ error: "Access denied: cannot create tasks for other patients" });
        }
        const { hasAccess } = await providerCollaborationService.checkProviderAccess(providerProfile.id, bodyPatientId);
        if (!hasAccess) {
          return res.status(403).json({ error: "Access denied: not authorized to create tasks for this patient" });
        }
      }

      const user = await storage.getUser(userId);
      const task = await providerCollaborationService.createTask(
        { ...req.body, createdById: userId },
        userId,
        user?.name || "Unknown",
        req.ip
      );
      auditLog(req, "create_task", "CollaborationTask", task.id, { title: task.title });
      res.status(201).json(task);
    } catch (error) {
      console.error("Create task error:", error);
      res.status(500).json({ error: "Failed to create task" });
    }
  });


