      const existingTask = await providerCollaborationService.getTaskById((req.params as any).id);
      if (!existingTask) {
        return res.status(404).json({ error: "Task not found" });
      }
      let authorized = existingTask.createdById === userId || existingTask.patientId === userId;
      if (!authorized && existingTask.careTeamId) {
        const provider = await storage.getProviderProfileByUserId(userId);
        if (provider) {
          authorized = await providerCollaborationService.isProviderTeamMember(provider.id, existingTask.careTeamId);
          if (!authorized && existingTask.assignedToId === provider.id) authorized = true;
        }
      }
      if (!authorized) {
        return res.status(403).json({ error: "Access denied" });
      }
      const user = await storage.getUser(userId);
      const task = await providerCollaborationService.updateTask(
        (req.params as any).id,
        req.body,
        userId,
        user?.name || "Unknown",
        req.ip
      );
      auditLog(req, "update_task", "CollaborationTask", (req.params as any).id);
