  // Create care plan note

  app.post("/api/collaboration/care-plans/:carePlanId/notes", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const carePlanId = (req.params as any).carePlanId as string;

      const ownerId = await providerCollaborationService.getCarePlanOwnerId(carePlanId);
      if (!ownerId) {
        return res.status(404).json({ error: "Care plan not found" });
      }

      let authorized = ownerId === userId;
      let authorRole = "patient";
      let notePatientId = userId;

      if (!authorized) {
        const provider = await storage.getProviderProfileByUserId(userId);
        if (provider) {
          const providerTeams = await providerCollaborationService.getCareTeams(provider.id);
          for (const team of providerTeams) {
            const sharedPlans = await providerCollaborationService.getSharedCarePlans(team.id);
            if (sharedPlans.some((sp: any) => sp.carePlan?.id === carePlanId || sp.carePlanId === carePlanId)) {
              authorized = true;
              authorRole = "provider";
              notePatientId = ownerId;
              break;
            }
          }
        }
      }

      if (!authorized) {
        return res.status(403).json({ error: "Access denied" });
      }

      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "User not found" });
      }

      const { noteType, title, content, priority, isPrivate, parentNoteId } = req.body as any;

      if (!content) {
        return res.status(400).json({ error: "Note content is required" });
      }

      const note = await providerCollaborationService.createCarePlanNote(
        {
          carePlanId,
          patientId: notePatientId,
          authorId: userId,
          authorName: `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim() || user.email || "User",
          authorRole,
          noteType: noteType || "general",
          title,
          content,
          priority: priority || "normal",
          isPrivate: isPrivate || false,
          parentNoteId,
        },
        userId,
        `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim() || user.email || "User",
        req.ip
      );

      auditLog(req, "create_care_plan_note", "CarePlanNote", note.id);
      res.status(201).json(note);
    } catch (error) {
      console.error("Create care plan note error:", error);
      res.status(500).json({ error: "Failed to create care plan note" });
    }
  });

