  app.get("/api/vitals/chart-data", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const months = parseInt((req.query as any).months as string) || 12;
      const vitalType = (req.query as any).type as string;

      const allRecords = await storage.getHealthRecordsByType(userId, "vital");

      const cutoff = new Date();
      cutoff.setMonth(cutoff.getMonth() - months);

      const filteredRecords = allRecords
        .filter(r => new Date(r.date) >= cutoff)
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

      interface VitalReading {
        date: string;
        value: number;
        unit: string;
        label: string;
        systolic?: number;
        diastolic?: number;
      }

      const vitalCategories: Record<string, VitalReading[]> = {
        blood_pressure: [],
        heart_rate: [],
        temperature: [],
        respiratory_rate: [],
        oxygen_saturation: [],
        weight: [],
        height: [],
        bmi: [],
      };

      for (const r of filteredRecords) {
        const details = r.details as any || {};
        const title = (r.title || "").toLowerCase();
        const dateStr = new Date(r.date).toISOString().split("T")[0];

        if (title.includes("blood pressure") || title.includes("bp") || details.systolic) {
          const systolic = details.systolic || details.value;
          const diastolic = details.diastolic;
          if (systolic) {
            vitalCategories.blood_pressure.push({
              date: dateStr,
              value: systolic,
              unit: "mmHg",
              label: `${systolic}/${diastolic || "?"}`,
              systolic,
              diastolic: diastolic || 0,
            });
          }
        } else if (title.includes("heart rate") || title.includes("pulse") || title.includes("hr")) {
          const val = details.value || details.heartRate;
          if (val) vitalCategories.heart_rate.push({ date: dateStr, value: val, unit: "bpm", label: `${val} bpm` });
        } else if (title.includes("temperature") || title.includes("temp")) {
          const val = details.value || details.temperature;
          if (val) vitalCategories.temperature.push({ date: dateStr, value: val, unit: details.unit || "\u00b0F", label: `${val}${details.unit || "\u00b0F"}` });
        } else if (title.includes("respiratory") || title.includes("breathing")) {
          const val = details.value || details.respiratoryRate;
          if (val) vitalCategories.respiratory_rate.push({ date: dateStr, value: val, unit: "breaths/min", label: `${val}/min` });
        } else if (title.includes("oxygen") || title.includes("spo2") || title.includes("o2 sat")) {
          const val = details.value || details.oxygenSaturation;
          if (val) vitalCategories.oxygen_saturation.push({ date: dateStr, value: val, unit: "%", label: `${val}%` });
        } else if (title.includes("weight") && !title.includes("birth")) {
          const val = details.value || details.weight;
          if (val) vitalCategories.weight.push({ date: dateStr, value: val, unit: details.unit || "lbs", label: `${val} ${details.unit || "lbs"}` });
        } else if (title.includes("height") || title.includes("stature")) {
          const val = details.value || details.height;
          if (val) vitalCategories.height.push({ date: dateStr, value: val, unit: details.unit || "in", label: `${val} ${details.unit || "in"}` });
        } else if (title.includes("bmi") || title.includes("body mass")) {
          const val = details.value || details.bmi;
          if (val) vitalCategories.bmi.push({ date: dateStr, value: val, unit: "kg/m\u00b2", label: `${val}` });
        }
      }

      const normalRanges: Record<string, { min: number; max: number; label: string }> = {
        blood_pressure: { min: 90, max: 120, label: "Normal: 90-120 systolic" },
        heart_rate: { min: 60, max: 100, label: "Normal: 60-100 bpm" },
        temperature: { min: 97.8, max: 99.1, label: "Normal: 97.8-99.1\u00b0F" },
        respiratory_rate: { min: 12, max: 20, label: "Normal: 12-20/min" },
        oxygen_saturation: { min: 95, max: 100, label: "Normal: 95-100%" },
        bmi: { min: 18.5, max: 24.9, label: "Normal: 18.5-24.9" },
      };

      if (vitalType) {
        const data = vitalCategories[vitalType] || [];
        res.json({
          type: vitalType,
          data,
          normalRange: normalRanges[vitalType] || null,
          count: data.length,
        });
      } else {
        const chartSummary = Object.entries(vitalCategories).map(([type, readings]) => ({
          type,
          count: readings.length,
          latest: readings.length > 0 ? readings[readings.length - 1] : null,
          normalRange: normalRanges[type] || null,
          data: readings,
        }));

        res.json({
          categories: chartSummary.filter(c => c.count > 0),
          totalReadings: filteredRecords.length,
          period: `${months} months`,
        });
      }
    } catch (error) {
      console.error("Vitals chart data error:", error);
      res.status(500).json({ error: "Failed to get vitals chart data" });
    }
  });


