  // Get a single episode with all its events

  app.get("/api/episodes-of-care/:id", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { episodesOfCareService } = await import("../episodes-of-care-service");
      const episode = await episodesOfCareService.getEpisodeById((req.params as any).id);
      if (!episode) {
        return res.status(404).json({ error: "Episode not found" });
      }
      if (episode.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      res.json(episode);
    } catch (error) {
      console.error("Get episode error:", error);
      res.status(500).json({ error: "Failed to get episode" });
    }
  });

  // Detect and create episodes from health records

  app.post("/api/episodes-of-care/detect", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { episodesOfCareService } = await import("../episodes-of-care-service");
      const result = await episodesOfCareService.detectAndCreateEpisodes(userId);
      res.json({
        success: true,
        episodesCreated: result.episodes.length,
        episodes: result.episodes,
        ungroupedEvents: result.ungroupedEvents.length,
      });
    } catch (error) {
      console.error("Detect episodes error:", error);
      res.status(500).json({ error: "Failed to detect episodes" });
    }
  });

  // Add an event to an episode

  app.post("/api/episodes-of-care/:id/events", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { healthRecordId, eventRole, clinicalRelevance } = req.body as any;
      const { episodesOfCareService } = await import("../episodes-of-care-service");
      const episode = await episodesOfCareService.getEpisodeById((req.params as any).id);
      if (!episode) {
        return res.status(404).json({ error: "Episode not found" });
      }
      if (episode.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (healthRecordId) {
        const healthRecord = await storage.getHealthRecord(healthRecordId);
        if (!healthRecord || healthRecord.userId !== userId) {
          return res.status(403).json({ error: "Access denied" });
        }
      }
      const event = await episodesOfCareService.addEventToEpisode(
        (req.params as any).id,
        healthRecordId,
        eventRole,
        clinicalRelevance
      );
      if (!event) {
        return res.status(500).json({ error: "Failed to add event" });
      }
      res.json(event);
    } catch (error) {
      console.error("Add event to episode error:", error);
      res.status(500).json({ error: "Failed to add event to episode" });
    }
  });

  // Remove an event from an episode

  app.delete("/api/episodes-of-care/:id/events/:healthRecordId", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { episodesOfCareService } = await import("../episodes-of-care-service");
      const episode = await episodesOfCareService.getEpisodeById((req.params as any).id);
      if (!episode) {
        return res.status(404).json({ error: "Episode not found" });
      }
      if (episode.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const success = await episodesOfCareService.removeEventFromEpisode(
        (req.params as any).id,
        (req.params as any).healthRecordId
      );
      if (!success) {
        return res.status(500).json({ error: "Failed to remove event" });
      }
      res.json({ success: true });
    } catch (error) {
      console.error("Remove event from episode error:", error);
      res.status(500).json({ error: "Failed to remove event from episode" });
    }
  });

  // Update episode status

  app.patch("/api/episodes-of-care/:id/status", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { status } = req.body as any;
      const { episodesOfCareService } = await import("../episodes-of-care-service");
      const existing = await episodesOfCareService.getEpisodeById((req.params as any).id);
      if (!existing) {
        return res.status(404).json({ error: "Episode not found" });
      }
      if (existing.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const episode = await episodesOfCareService.updateEpisodeStatus((req.params as any).id, status);
      if (!episode) {
        return res.status(404).json({ error: "Episode not found" });
      }
      res.json(episode);
    } catch (error) {
      console.error("Update episode status error:", error);
      res.status(500).json({ error: "Failed to update episode status" });
    }
  });

